{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE or replace table snitch_db.maplemonk.return_fact_items as WITH sales_data AS ( SELECT sku_group, order_name, line_item_id, sku, customer_name, phone, order_timestamp::date AS order_date, CASE when webshopney in (\'Shopney\',\'Appbrew\') then \'Appbrew\' when webshopney = \'Snitch_IOS\' and tags like \'%Snitch_IOS%\' then \'IOS\' when webshopney = \'Snitch_IOS\' and tags like \'%Snitch_Android%\' then \'Android\' ELSE \'Web\' END AS channel, state, quantity AS sales_qty, gross_sales as sales_value FROM snitch_db.maplemonk.fact_items_snitch where lower(ifnull(discount_code,\'n\')) not like \'%influ%\' and order_name not in (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') and tags not in (\'FLITS_LOGICERP\') and order_timestamp::date > \'2023-10-01\' ), first_order_date AS ( SELECT sku_group, MIN(order_date) AS first_order_date FROM sales_data GROUP BY sku_group ), live_date AS ( SELECT a.id, a.status, a.published_at AS live_date, b.sku_group FROM snitch_db.maplemonk.shopifyindia_new_products a LEFT JOIN snitch_db.maplemonk.availability_master_v2 b ON a.id = b.id ), live_date_final as ( SELECT COALESCE(a.sku_group, b.sku_group) AS sku_group, CASE WHEN a.live_date < b.first_order_date THEN a.live_date::date ELSE b.first_order_date::date END AS live_date FROM live_date a FULL OUTER JOIN first_order_date b ON a.sku_group = b.sku_group ), category as ( select sku_group, product_type, case when product_type in (\'Joggers & Trackpants\',\'Cargo Pants\',\'Boxers\',\'Jeans\',\'Night Suit & Pyjamas\',\'Trousers\',\'Chinos\',\'Shorts\') then \'bottom_wear\' when product_type in (\'Shirt\',\'Overshirt\',\'Hoodies\',\'Sweaters\',\'T-Shirts\',\'Sweatshirts\',\'Shirts\',\'Jackets\',\'Blazers\') then \'top_wear\' when product_type in (\'Accessories\',\'Sunglasses\',\'Shoes\',\'Inner Wear\',\'Perfumes\') then \'accessories\' else \'others\' end as top_bottom from snitch_db.maplemonk.metafields_data ), final_sales_table as ( select a.*, b.live_date, c.product_type, c.top_bottom from sales_data a left join live_date_final b on a.sku_group = b.sku_group left join category c on a.sku_group = c.sku_group ), fit AS ( SELECT SUBSTRING(id, POSITION(\'Product/\' IN id) + LENGTH(\'Product/\')) AS id, REPLACE(A.value:key, \'\"\', \'\') AS key_type, REPLACE(A.value:value, \'\"\', \'\') AS fit FROM snitch_db.maplemonk.metafields_products_graph_ql, LATERAL FLATTEN (input => metafields) A WHERE key_type = \'fit\' ), sku_group_fit as ( select a.sku_group, b.fit from snitch_db.maplemonk.availability_master_v2 a left join fit b on a.id = b.id ), returns_data_pre as ( select distinct \"Order ID\" as order_name, \"Product SKU Code\" as sku_list, \"RVP Reason\" as reason_list from snitch_db.maplemonk.snitch_clickpost_track_order_dashboard_report where lower(\"Courier Partner\") like \'%reverse%\' and \"Pickup Date\" is not null and \"Pickup Date\" != \'\' ), cleaned_data AS ( SELECT order_name, RTRIM(REPLACE(sku_list, \', \', \',\'), \',\') AS cleaned_sku_list, RTRIM(REPLACE(reason_list, \', \', \',\'), \',\') AS cleaned_reason_list FROM returns_data_pre ), split_sku AS ( SELECT order_name, REPLACE(VALUE, \'\"\', \'\') AS sku, INDEX AS sku_index FROM cleaned_data, LATERAL FLATTEN(INPUT => SPLIT(cleaned_sku_list, \',\')) ), split_reason AS ( SELECT order_name, REPLACE(VALUE, \'\"\', \'\') AS reason, INDEX AS reason_index FROM cleaned_data, LATERAL FLATTEN(INPUT => SPLIT(cleaned_reason_list, \',\')) ), final_mapping AS ( SELECT s.order_name, s.sku, COALESCE(r.reason, LAST_VALUE(r.reason) OVER ( PARTITION BY s.order_name ORDER BY r.reason_index ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING )) AS reason FROM split_sku s LEFT JOIN split_reason r ON s.order_name = r.order_name AND s.sku_index = r.reason_index ), returns_data_pre2 as ( SELECT DISTINCT order_name, sku, LEFT(sku, LENGTH(sku) - CHARINDEX(\'-\', REVERSE(sku))) AS sku_group, reason FROM final_mapping ), --changing name returns_data as ( select sku, sku_group, order_name as order_id, count(distinct sku) as return_qty, reason as return_reasons, case when lower(reason) = \'product looks different from website\' then \'product_different_from_website\' when lower(reason) IN (\'i do not like the product\', \'product quality issue\') then \'quality\' when lower(reason) IN (\'size is too large\', \'size is too small\', \'size or fit issue\') then \'size\' when lower(reason) IN (\'wrong item shipped\', \'i received a defective item\', \'wrong item received\', \'wrong size shipped\', \'wrong or defective product\') then \'wpr\' when lower(reason) = \'delivery was delayed\' then \'delivery_delayed\' when lower(reason) = \'i change my mind\' then \'mind_change\' end as reason from returns_data_pre2 group by 1,2,3,5,6 ), return_before_19 as ( select sku, LEFT(sku, LENGTH(sku) - CHARINDEX(\'-\', REVERSE(sku))) AS sku_group, order_id, quantity as return_qty, return_reasons, case when lower(return_reasons) = \'product looks different from website\' then \'product_different_from_website\' when lower(return_reasons) IN (\'i do not like the product\', \'product quality issue\') then \'quality\' when lower(return_reasons) IN (\'size is too large\', \'size is too small\', \'size or fit issue\') then \'size\' when lower(return_reasons) IN (\'wrong item shipped\', \'i received a defective item\', \'wrong item received\', \'wrong size shipped\', \'wrong or defective product\') then \'wpr\' when lower(return_reasons) = \'delivery was delayed\' then \'delivery_delayed\' when lower(return_reasons) = \'i change my mind\' then \'mind_change\' end as reason from snitch_db.maplemonk.ecoreturns_final_returns where status != \'REJECTED\' AND REQUEST_TYPE in (\'Return\') ), main_data as ( select a.*, ifnull(b.return_qty,0) as return_qty, coalesce(b.return_reasons,\'not_returned\') as return_reasons, coalesce(b.reason,\'not_returned\') as reason, c.live_date, d.product_type as category, d.top_bottom, e.fit from sales_data a left join returns_data b on a.sku = b.sku and a.sku_group = b.sku_group and cast(a.order_name as varchar) = cast(b.order_id as varchar) left join live_date_final c on a.sku_group = c.sku_group left join category d on a.sku_group = d.sku_group left join sku_group_fit e on a.sku_group = e.sku_group where a.order_date >= \'2024-11-20\' and channel != \'Web\' union select a.*, ifnull(b.return_qty,0) as return_qty, coalesce(b.return_reasons,\'not_returned\') as return_reasons, coalesce(b.reason,\'not_returned\') as reason, c.live_date, d.product_type as category, d.top_bottom, e.fit from sales_data a left join return_before_19 b on a.sku = b.sku and a.sku_group = b.sku_group and cast(a.order_name as varchar) = cast(b.order_id as varchar) left join live_date_final c on a.sku_group = c.sku_group left join category d on a.sku_group = d.sku_group left join sku_group_fit e on a.sku_group = e.sku_group where a.order_date < \'2024-11-20\' union select a.*, ifnull(b.return_qty,0) as return_qty, coalesce(b.return_reasons,\'not_returned\') as return_reasons, coalesce(b.reason,\'not_returned\') as reason, c.live_date, d.product_type as category, d.top_bottom, e.fit from sales_data a left join return_before_19 b on a.sku = b.sku and a.sku_group = b.sku_group and cast(a.order_name as varchar) = cast(b.order_id as varchar) left join live_date_final c on a.sku_group = c.sku_group left join category d on a.sku_group = d.sku_group left join sku_group_fit e on a.sku_group = e.sku_group where a.order_date >= \'2024-11-20\' and a.channel = \'Web\' ), exchange as ( SELECT order_name, sku_group, line_item_sales, gross_sales, tags, REGEXP_SUBSTR(tags, \'Snitch-RMS-Exchange for ([0-9]+)\', 1, 1, \'e\', 1) AS original_line_item_id FROM snitch_db.maplemonk.fact_items_snitch where POSITION(\'Snitch-RMS-Exchange for\' IN tags) > 0 ), main_data2 as ( select SKU_GROUP, ORDER_NAME, SKU, line_item_id, CUSTOMER_NAME, PHONE, ORDER_DATE, CHANNEL, STATE, SALES_QTY, SALES_VALUE, return_qty, case when trim(line_item_id) in (select distinct trim(original_line_item_id) from exchange) then 0 else return_qty end as return_qty_real, RETURN_REASONS, REASON, LIVE_DATE, CATEGORY, TOP_BOTTOM, FIT from main_data ) select *, case when return_qty !=0 then (sales_value/sales_qty)*return_qty_real else 0 end as return_value from main_data2 ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            